    initialSelectedLabels,
  )

  /* Selection */
  const onLabelSelect = (labelId: string) => {
    if (!selectedLabelIds.includes(labelId))
      setSelectedLabelIds([...selectedLabelIds, labelId])
    else setSelectedLabelIds(selectedLabelIds.filter((id) => id !== labelId))
  }
  const onClearSelection = () => {
    setSelectedLabelIds([])
  }
  const onSubmit = () => {
    data.issue.labelIds = selectedLabelIds // pretending to persist changes
  }
  const onCancel = () => {
    setSelectedLabelIds(initialSelectedLabels)
  }

  /* Filtering */
  const [filteredLabels, setFilteredLabels] = React.useState(data.labels)
  const [query, setQuery] = React.useState('')
  const onSearchInputChange: React.ChangeEventHandler<HTMLInputElement> = (
    event,
  ) => {
    const query = event.currentTarget.value
    setQuery(query)
    if (query === '') setFilteredLabels(data.labels)
    else {
      setFilteredLabels(
        data.labels
          .map((label) => {
            if (label.name.toLowerCase().startsWith(query))
              return {
                priority: 1,
                label,
              }
            else if (label.name.toLowerCase().includes(query))
              return {
                priority: 2,
                label,
              }
            else if (label.description?.toLowerCase().includes(query))
              return {
                priority: 3,
                label,
              }
            else
              return {
                priority: -1,
                label,
              }
          })
          .filter((result) => result.priority > 0)
          .map((result) => result.label),
      )
    }
  }
  const sortingFn = (
    itemA: {
      id: string
    },
    itemB: {
      id: string
    },
  ) => {
    const initialSelectedIds = data.issue.labelIds
    if (
      initialSelectedIds.includes(itemA.id) &&
      initialSelectedIds.includes(itemB.id)
    )
      return 1
    else if (initialSelectedIds.includes(itemA.id)) return -1
    else if (initialSelectedIds.includes(itemB.id)) return 1
    else return 1
  }
  const itemsToShow = query ? filteredLabels : data.labels.sort(sortingFn)
  return (
    <>
      <SelectPanel
        title="Select labels"
        onSubmit={onSubmit}
        onCancel={onCancel}
        onClearSelection={onClearSelection}
      >
        <SelectPanel.Button>Assign label</SelectPanel.Button>

        <SelectPanel.Header>
          <SelectPanel.SearchInput
            aria-label="Search"
            onChange={onSearchInputChange}
          />
        </SelectPanel.Header>

        {itemsToShow.length === 0 ? (
          <SelectPanel.Message
            variant="empty"
            title={`No labels found for "${query}"`}
          >
            Try a different search term
          </SelectPanel.Message>
        ) : (
          <ActionList>
            {itemsToShow.map((label) => (
              <ActionList.Item
                key={label.id}
                onSelect={() => onLabelSelect(label.id)}
