() => {
  const initialChannels = {
    GitHub: false,
    Email: false,
  }
  const [channels, setChannels] = React.useState(initialChannels)
  const [onlyFailures, setOnlyFailures] = React.useState(false)
  const onSubmit = () => {
    // eslint-disable-next-line no-console
    console.log('form submitted')
  }
  const onCancel = () => {
    setChannels(initialChannels)
  }
  const toggleChannel = (channel: keyof typeof channels) => {
    setChannels({
      ...channels,
      [channel]: !channels[channel],
    })
  }
  const channelsEnabled = channels.GitHub || channels.Email
  return (
    <>
      <h1>Short SelectPanel</h1>
      <p>
        Use <code>height=fit-content</code> to match height of contents
      </p>
      <SelectPanel
        title="Select notification channels"
        onSubmit={onSubmit}
        onCancel={onCancel}
      >
        <SelectPanel.Button>
          <Text className={classes.TextMuted}>Notify me:</Text>{' '}
          {Object.keys(channels)
            .filter((channel) => channels[channel as keyof typeof channels])
            .join(', ') || 'Never'}
          {onlyFailures && channelsEnabled && ' (Failed workflows only)'}
        </SelectPanel.Button>

        <ActionList>
          <ActionList.Item
            selected={channels.GitHub}
            onSelect={() => toggleChannel('GitHub')}
          >
            On GitHub
          </ActionList.Item>
          <ActionList.Item
            selected={channels.Email}
            onSelect={() => toggleChannel('Email')}
          >
            Email
          </ActionList.Item>
          <div
            role="none"
            className={`${classes.TransitionBox} ${channelsEnabled ? classes.TransitionBoxVisible : classes.TransitionBoxHidden}`}
          >
            <ActionList.Divider />
            <ActionList.Item
              selected={onlyFailures}
              onSelect={() => setOnlyFailures(!onlyFailures)}
            >
              Only notify for failed workflows
            </ActionList.Item>
          </div>
        </ActionList>
        <SelectPanel.Footer />
      </SelectPanel>
    </>
  )
}

