() => {
  /* Open state */
  const [menuOpen, setMenuOpen] = React.useState(false)
  const [selectPanelOpen, setSelectPanelOpen] = React.useState(false)

  /* Selection */
  const [selectedSetting, setSelectedSetting] =
    React.useState<string>('All activity')
  const initialCustomEvents: string[] = []
  const [selectedCustomEvents, setSelectedCustomEvents] =
    React.useState<string[]>(initialCustomEvents)
  const onEventSelect = (event: string) => {
    if (!selectedCustomEvents.includes(event))
      setSelectedCustomEvents([...selectedCustomEvents, event])
    else
      setSelectedCustomEvents(
        selectedCustomEvents.filter((name) => name !== event),
      )
  }
  const itemsToShow = [
    'Issues',
    'Pull requests',
    'Releases',
    'Discussions',
    'Security alerts',
  ]
  return (
    <>
      <h1>Open in modal from ActionMenu</h1>

      <ActionMenu open={menuOpen} onOpenChange={(value) => setMenuOpen(value)}>
        <ActionMenu.Button leadingVisual={EyeIcon}>
          {selectedSetting === 'Ignore' ? 'Watch' : 'Unwatch'}
        </ActionMenu.Button>
        <ActionMenu.Overlay width="medium">
          <ActionList selectionVariant="single">
            <ActionList.Item
              selected={selectedSetting === 'Participating and @mentions'}
              onSelect={() => setSelectedSetting('Participating and @mentions')}
            >
              Participating and @mentions
              <ActionList.Description variant="block">
                Only receive notifications from this repository when
                participating or @mentioned.
              </ActionList.Description>
            </ActionList.Item>
            <ActionList.Item
              selected={selectedSetting === 'All activity'}
              onSelect={() => setSelectedSetting('All activity')}
            >
              All activity
              <ActionList.Description variant="block">
                Notified of all notifications on this repository.
              </ActionList.Description>
            </ActionList.Item>
            <ActionList.Item
              selected={selectedSetting === 'Ignore'}
              onSelect={() => setSelectedSetting('Ignore')}
            >
              Ignore
              <ActionList.Description variant="block">
                Never be notified.
              </ActionList.Description>
            </ActionList.Item>
            <ActionList.Item
              selected={selectedSetting === 'Custom'}
              onSelect={() => {
                setMenuOpen(false)
                setSelectPanelOpen(true)
              }}
            >
              Custom
              <ActionList.TrailingVisual>
                <ArrowRightIcon />
              </ActionList.TrailingVisual>
              <ActionList.Description variant="block">
                Select events you want to be notified of in addition to
                participating and @mentions.
              </ActionList.Description>
            </ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
      <SelectPanel
        variant="modal"
        title="Custom"
        open={selectPanelOpen}
        onSubmit={() => {
          setSelectedSetting('Custom')
          setSelectPanelOpen(false)
          setMenuOpen(false)
        }}
        onCancel={() => {
          setSelectedCustomEvents(initialCustomEvents)
          setSelectPanelOpen(false)
          setMenuOpen(true)
        }}
      >
        <ActionList>
          {itemsToShow.map((item) => (
            <ActionList.Item
              key={item}
              onSelect={() => onEventSelect(item)}
              selected={selectedCustomEvents.includes(item)}
            >
              {item}
            </ActionList.Item>
          ))}
        </ActionList>
        <SelectPanel.Footer />
      </SelectPanel>
    </>
  )
}

