  )
  const sortingFn = (ref: { id: string }) => {
    if (ref.id === savedInitialRef) return -1
    else return 1
  }
  const itemsToShow = query
    ? filteredRefs
    : data[selectedFilter].sort(sortingFn)
  return (
    <>
      <h1>With Filter Buttons {savedInitialRef}</h1>

      <SelectPanel
        title="Switch branches/tags"
        onSubmit={onSubmit}
        onCancel={onCancel}
      >
        <SelectPanel.Button
          leadingVisual={GitBranchIcon}
          trailingVisual={TriangleDownIcon}
        >
          {savedInitialRef}
        </SelectPanel.Button>

        <SelectPanel.Header>
          <SelectPanel.SearchInput onChange={onSearchInputChange} />

          <div id="filters" className={classes.FilterButtons}>
            <Button
              variant="invisible"
              style={{
                fontWeight:
                  selectedFilter === 'branches'
                    ? 'var(--base-text-weight-medium)'
                    : 'var(--base-text-weight-normal)',
                color: 'var(--fgColor-default)',
              }}
              onClick={() => setSelectedFilter('branches')}
              count={20}
            >
              Branches
            </Button>
            <Button
              variant="invisible"
              style={{
                fontWeight:
                  selectedFilter === 'tags'
                    ? 'var(--base-text-weight-medium)'
                    : 'var(--base-text-weight-normal)',
                color: 'var(--fgColor-default)',
              }}
              onClick={() => setSelectedFilter('tags')}
              count={8}
            >
              Tags
            </Button>
          </div>
        </SelectPanel.Header>

        {itemsToShow.length === 0 ? (
          <SelectPanel.Message
            variant="empty"
            title={`No labels found for "${query}"`}
          >
            Try a different search term
          </SelectPanel.Message>
        ) : (
          <ActionList>
            {itemsToShow.map((item) => (
              <ActionList.Item
                key={item.id}
                selected={selectedRef === item.id}
                onSelect={() => setSelectedRef(item.id)}
              >
                {item.name}
                <ActionList.TrailingVisual>
                  {item.trailingInfo}
                </ActionList.TrailingVisual>
              </ActionList.Item>
            ))}
          </ActionList>
        )}

        <SelectPanel.Footer>
          <SelectPanel.SecondaryAction
            variant="link"
            href={`/${selectedFilter}`}
          >
            View all {selectedFilter}
          </SelectPanel.SecondaryAction>
        </SelectPanel.Footer>
      </SelectPanel>
    </>
  )
}
